function getMarketplaceStrategy(id) {
  return MARKETPLACE_STRATEGIES.find((s) => s.id === id) || null;
}

/* Strategies rotated out of the weekly lineup stay in MARKETPLACE_STRATEGIES
   with `archived: true` (2026-09-19) - buyers own them per strategy id, so
   deleting an entry would take away something they paid for (My Purchases,
   "Load into Builder" and downloads all resolve ids through this catalog).
   Anything that means "what's on offer THIS week" - the Strategy of the Week
   page, the homepage teaser - must go through this instead of reading
   MARKETPLACE_STRATEGIES directly; ownership lookups
   (getMarketplaceStrategy / getOwnedMarketplaceStrategies) deliberately
   still see archived entries. The backend refuses new checkouts for archived
   ids too - see ARCHIVED_STRATEGY_IDS in marketplace_strategies.py. */
function getActiveMarketplaceStrategies() {
  return MARKETPLACE_STRATEGIES.filter((s) => !s.archived);
}

/* ------------------------------------------------------------
   BACKEND API BASE (2026-08-31 addition) - same hostname-based detection
   as index_1.html's and strategy-detail.html's own PRODUCTION_API_BASE/
   STAGING_API_BASE/API_BASE (see either file's comment for the full
   reasoning) - a separate, distinctly-named copy here rather than reusing
   theirs, so this shared file works standalone on the two pages that
   never had a copy of their own (strategy-of-the-week.html,
   my-purchases.html) without risking a `const API_BASE` collision on the
   two pages that already declare their own in an inline <script> sharing
   this same global scope.
   ------------------------------------------------------------ */
const MARKETPLACE_PRODUCTION_API_BASE = 'https://algopuzzle-api.onrender.com';
const MARKETPLACE_STAGING_API_BASE = 'https://algopuzzle-api-staging.onrender.com';
const MARKETPLACE_IS_STAGING = window.location.hostname === 'algopuzzle-frontend-staging.onrender.com';
const MARKETPLACE_IS_LOCAL_DEV = ['localhost', '127.0.0.1', ''].includes(window.location.hostname) || window.location.protocol === 'file:';
const MARKETPLACE_API_BASE = MARKETPLACE_IS_LOCAL_DEV
  ? (window.location.origin.includes('null') || window.location.protocol === 'file:'
      ? 'http://127.0.0.1:8000'
      : window.location.origin.replace(/:\d+$/, ':8000'))
  : MARKETPLACE_IS_STAGING
    ? MARKETPLACE_STAGING_API_BASE
    : MARKETPLACE_PRODUCTION_API_BASE;

/* ------------------------------------------------------------
   OWNERSHIP (real, 2026-08-31 - replaces the earlier localStorage mock)
   ------------------------------------------------------------
   Backed by a real purchase record now (GET /api/marketplace/purchases -
   see main.py/db.py) instead of localStorage. Fetched ONCE per page load
   into _ownedStrategyIdsCache by initMarketplaceOwnership() - every page
   using this file calls `await initMarketplaceOwnership()` before its
   first render (see strategy-of-the-week.html / strategy-detail.html /
   my-purchases.html / index_1.html's Purchases sub-tab for the call
   sites). After that resolves, getOwnedStrategyIds()/isStrategyOwned()/
   getOwnedMarketplaceStrategies() stay fully synchronous, same signatures
   as the old mock - no caller needed to change beyond adding that one
   await at the top of its render path.
   ------------------------------------------------------------ */
let _ownedStrategyIdsCache = null;
let _ownedStrategyIdsPromise = null;

async function initMarketplaceOwnership(forceRefresh) {
  if (_ownedStrategyIdsCache && !forceRefresh) return _ownedStrategyIdsCache;
  if (_ownedStrategyIdsPromise && !forceRefresh) return _ownedStrategyIdsPromise;
  _ownedStrategyIdsPromise = (async () => {
    try {
      // Ownership is account-based now (2026-08-31, see marketplace-auth.js's
      // header comment) - the Authorization header IS the query, not just
      // an optional extra. Not logged in -> getValidAccessToken() resolves
      // null -> no header sent -> backend correctly returns owned_ids: [].
      const token = typeof getValidAccessToken === 'function' ? await getValidAccessToken() : null;
      const headers = token ? { Authorization: `Bearer ${token}` } : {};
      const res = await fetch(`${MARKETPLACE_API_BASE}/api/marketplace/purchases`, { credentials: 'include', headers });
      const data = res.ok ? await res.json() : {};
      _ownedStrategyIdsCache = Array.isArray(data.owned_ids) ? data.owned_ids : [];
    } catch (err) {
      console.warn('AlgoPuzzle marketplace: could not fetch purchases - treating as nothing owned.', err);
      _ownedStrategyIdsCache = [];
    }
    return _ownedStrategyIdsCache;
  })();
  return _ownedStrategyIdsPromise;
}

function getOwnedStrategyIds() {
  // Sync read of whatever initMarketplaceOwnership() last resolved to -
  // returns [] if that hasn't happened yet rather than throwing, so a
  // caller that forgets the await fails soft (nothing shown as owned)
  // instead of crashing the page.
  return _ownedStrategyIdsCache || [];
}

function isStrategyOwned(id) {
  return getOwnedStrategyIds().includes(id);
}

function getOwnedMarketplaceStrategies() {
  const ownedIds = getOwnedStrategyIds();
  return MARKETPLACE_STRATEGIES.filter((s) => ownedIds.includes(s.id));
}

/* ------------------------------------------------------------
   CHECKOUT (real, 2026-08-31) - creates a real Stripe Checkout Session for
   one PAID strategy and returns its hosted URL, or throws with a message
   suitable to show the buyer directly (main.py's HTTPException detail
   text, e.g. "This strategy hasn't been purchased yet." never applies
   here - that's the download-side check; checkout-side failures look
   more like "Marketplace purchases are not configured"). Shared by
   strategy-of-the-week.html and strategy-detail.html's purchase-confirm
   button (see those files) - never called for the free strategy, which
   skips checkout entirely (see the `tier === 'free'` branch at each call
   site and MARKETPLACE_STRATEGY_TIERS in marketplace_strategies.py on the
   backend, which independently refuses to price a free id even if this
   were called for one).
   ------------------------------------------------------------ */
async function createStrategyCheckoutUrl(strategyId) {
  // Requires login as of 2026-08-31 (see marketplace-auth.js's header
  // comment) - the caller is expected to have already confirmed a valid
  // session before calling this (see strategy-of-the-week.html /
  // strategy-detail.html's purchaseConfirmBtn handlers), but a 401 is
  // still handled explicitly here (session could have expired between
  // page load and click) by throwing with `.isAuthRequired = true` so the
  // caller can show the login modal and retry, rather than a raw error.
  const token = await getValidAccessToken();
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${MARKETPLACE_API_BASE}/api/billing/checkout/strategy`, {
    method: 'POST',
    credentials: 'include',
    headers,
    body: JSON.stringify({ strategy_id: strategyId }),
  });
  if (!res.ok) {
    const detail = await res.json().catch(() => ({}));
    const err = new Error(detail.detail || `Could not start checkout (HTTP ${res.status}).`);
    if (res.status === 401) err.isAuthRequired = true;
    throw err;
  }
  const data = await res.json();
  if (!data.url) throw new Error('Stripe did not return a checkout URL.');
  return data.url;
}
